/** Local stock logos live in /public/logos/{TICKER}.png (generated by scripts/download_stock_logos.py). */

let manifest: Set<string> | null = null;
let manifestPromise: Promise<Set<string>> | null = null;

export function logoSrc(symbol: string): string {
  const sym = (symbol || "").trim().toUpperCase();
  return `/logos/${encodeURIComponent(sym)}.png`;
}

async function loadManifest(): Promise<Set<string>> {
  if (manifest) return manifest;
  if (!manifestPromise) {
    manifestPromise = fetch("/logos/manifest.json")
      .then((r) => (r.ok ? r.json() : []))
      .then((list: unknown) => {
        manifest = new Set(
          Array.isArray(list) ? list.map((s) => String(s).trim().toUpperCase()).filter(Boolean) : [],
        );
        return manifest;
      })
      .catch(() => {
        manifest = new Set();
        return manifest;
      });
  }
  return manifestPromise;
}

/** Optional fast path — returns true when manifest says we have a local logo file. */
export async function hasLocalLogo(symbol: string): Promise<boolean> {
  const sym = (symbol || "").trim().toUpperCase();
  if (!sym) return false;
  const m = await loadManifest();
  return m.has(sym);
}

export function hasLocalLogoSync(symbol: string): boolean {
  const sym = (symbol || "").trim().toUpperCase();
  if (!sym || !manifest) return false;
  return manifest.has(sym);
}

/** Warm manifest in the background (e.g. app boot). */
export function preloadLogoManifest(): void {
  void loadManifest();
}
